    const onAbort = () => {
        const addon = model.addon;
        if (addon?.cancel) {
            addon.cancel.call(addon).catch((err) => {
                requestLogger.warn(`[cancel] addon.cancel() rejected during batch abort for modelId=${modelId}: ${err instanceof Error ? err.message : String(err)}`);
            });
        }
    };
    signal.addEventListener('abort', onAbort, { once: true });
    if (signal.aborted)
        onAbort();
    scope.defer(() => {
        signal.removeEventListener('abort', onAbort);
    });
    const addonPrompts = prompts.map((prompt) => buildBatchPrompt(prompt, renderOptions));
    const modelStart = nowMs();
    const response = await runBatchModel(model, addonPrompts);
    const ids = response.ids;
    yield { type: 'ids', ids };
